 20→  { label: "후보자 검증", href: "/verification" },
 21→  { label: "채용 진행", href: "/hiring-progress" },
 22→  { label: "채용 완료", href: "/hiring-complete" },
 23→  { label: "학과장 Action", href: "/dean-action", hideFor: ["VIP", "ADMIN"] },
 24→];
 25→
 26→function getVisibleMenu(role: string): MenuItem[] {
 27→  return MENU_ITEMS.filter((item) => {
 28→    if (item.hideFor && item.hideFor.includes(role)) return false;
 29→    return true;
 30→  });
 31→}
