 1→import { redirect } from "next/navigation";
 2→import { requireUser, listUsers } from "@/lib/auth";
 3→import { getDepartmentOptions } from "@/lib/queries";
 4→import { checkPermission, getAllRoles, getPermissionsForRole } from "@/lib/permissions";
 5→import AccountPage from "@/components/account-page";
 6→
 7→export default async function AccountManagementPage() {
 8→  const user = await requireUser();
 9→
10→  // VIP/ADMIN이 아닌 역할은 이 페이지 접근 불가
11→  const canViewUsers = checkPermission(user.role, "system.users", "view");
12→  if (!canViewUsers) {
13→    redirect("/");
14→  }
15→
16→  const users = listUsers();
17→  const departments = getDepartmentOptions();
18→  const canViewPermissions = checkPermission(user.role, "system.permissions", "view");
19→
20→  let roles: string[] = [];
21→  let permissions: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
22→
23→  if (canViewPermissions) {
24→    roles = getAllRoles();
25→    for (const role of roles) {
26→      permissions[role] = getPermissionsForRole(role);
27→    }
28→  }
29→
30→  return (
31→    <AccountPage
32→      currentRole={user.role}
33→      users={users}
34→      departments={departments}
35→      roles={roles}
36→      permissions={permissions}
37→      canViewPermissions={canViewPermissions}
38→    />
39→  );
40→}
